"""Create audiobook from Paul Graham essays."""

import os
import re
import subprocess
import sys
import html
from html.parser import HTMLParser
from typing import List

import requests


URLS = [
    "https://paulgraham.com/ds.html",  # Do Things that Don't Scale
    "https://paulgraham.com/foundermode.html",  # Founder Mode
]


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self._chunks: List[str] = []
        self._skip = False

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self._skip = True
            return
        if tag in ("p", "br", "div", "tr", "li", "h1", "h2", "h3"):
            self._chunks.append("\n")

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            self._skip = False
            return
        if tag in ("p", "div", "tr", "li"):
            self._chunks.append("\n")

    def handle_data(self, data):
        if self._skip:
            return
        if data:
            self._chunks.append(data)

    def text(self) -> str:
        raw = "".join(self._chunks)
        return html.unescape(raw)


def fetch_article_content(url: str) -> str:
    result = subprocess.run(["curl", "-s", url], capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"curl failed for {url}")
    html_text = result.stdout

    parser = TextExtractor()
    parser.feed(html_text)
    text = parser.text()

    # Normalize whitespace and trim
    text = re.sub(r"\r", "", text)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    text = text.strip()

    # Remove common nav/footer lines
    nav_lines = {
        "Paul Graham",
        "Essays",
        "Books",
        "RSS",
        "Twitter",
        "Email",
        "Work",
        "About",
    }
    filtered_lines = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            filtered_lines.append("")
            continue
        if line in nav_lines:
            continue
        if line.lower() in {"home", "essays", "rss", "twitter", "email"}:
            continue
        filtered_lines.append(line)

    text = "\n".join(filtered_lines)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()

    return text


def verify_content(text: str, expected_min_chars: int = 1000) -> bool:
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")
        return False
    return True


def clean_text_for_tts(text: str) -> str:
    text = re.sub(r"http[s]?://\S+", "", text)
    text = re.sub(r"\[\d+\]", "", text)
    text = re.sub(r"\s+", " ", text)
    text = re.sub(r"[^\w\s.,!?;:\'\"()-]", "", text)
    return text.strip()


def chunk_text(text: str, max_chars: int = 4000) -> List[str]:
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks: List[str] = []
    current = ""
    for sentence in sentences:
        if not sentence:
            continue
        if len(current) + len(sentence) + 1 <= max_chars:
            current += sentence + " "
        else:
            if current:
                chunks.append(current.strip())
            current = sentence + " "
    if current:
        chunks.append(current.strip())
    return chunks


def concatenate_audio(audio_files: List[str], output_path: str) -> bool:
    if not audio_files:
        return False
    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w", encoding="utf-8") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    result = subprocess.run(
