        capture_output=True,
        text=True,
    )

    for fpath in audio_files:
        try:
            os.unlink(fpath)
        except OSError:
            pass
    try:
        os.unlink(list_file)
    except OSError:
        pass

    if result.returncode != 0:
        print(result.stderr)
        return False
    return True


def create_with_elevenlabs(text: str, output_path: str) -> bool:
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        return False

    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel
    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        response = requests.post(
            f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
            headers={
                "xi-api-key": api_key,
                "Content-Type": "application/json",
            },
            json={
                "text": chunk,
                "model_id": "eleven_turbo_v2_5",
                "voice_settings": {"stability": 0.5, "similarity_boost": 0.75},
            },
            timeout=60,
        )
        if response.status_code == 200:
            with open(chunk_file, "wb") as f:
                f.write(response.content)
            audio_files.append(chunk_file)
        else:
            print(f"ElevenLabs error: {response.status_code} - {response.text}")
            return False

    return concatenate_audio(audio_files, output_path)


def create_with_openai(text: str, output_path: str) -> bool:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        response = requests.post(
            "https://api.openai.com/v1/audio/speech",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            json={
                "model": "tts-1",
                "input": chunk,
                "voice": "onyx",
                "response_format": "mp3",
            },
            timeout=60,
        )
        if response.status_code == 200:
            with open(chunk_file, "wb") as f:
                f.write(response.content)
            audio_files.append(chunk_file)
        else:
            print(f"OpenAI TTS error: {response.status_code} - {response.text}")
            return False

    return concatenate_audio(audio_files, output_path)


def create_with_gtts(text: str, output_path: str) -> bool:
    try:
        from gtts import gTTS
    except Exception as exc:
        print(f"gTTS not available: {exc}")
        return False

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        tts = gTTS(text=chunk, lang="en", slow=False)
        tts.save(chunk_file)
        audio_files.append(chunk_file)

    return concatenate_audio(audio_files, output_path)


def create_audiobook(text: str, output_path: str) -> bool:
    if os.environ.get("ELEVENLABS_API_KEY"):
        print("Using ElevenLabs TTS")
        if create_with_elevenlabs(text, output_path):
            return True
        print("ElevenLabs failed, falling back to OpenAI TTS")

    if os.environ.get("OPENAI_API_KEY"):
        print("Using OpenAI TTS")
        if create_with_openai(text, output_path):
            return True
        print("OpenAI TTS failed, falling back to gTTS")

    print("Using gTTS")
    return create_with_gtts(text, output_path)


def extract_title_from_html(html_text: str) -> str:
    match = re.search(r"<title>(.*?)</title>", html_text, re.IGNORECASE | re.DOTALL)
    if not match:
        return ""
    title = html.unescape(match.group(1))
    title = re.sub(r"\s+", " ", title).strip()
    return title


def fetch_title(url: str) -> str:
    result = subprocess.run(["curl", "-s", url], capture_output=True, text=True)
    if result.returncode != 0:
        return ""
    return extract_title_from_html(result.stdout)


def main() -> int:
    all_text = []

    for url in URLS:
        print(f"Fetching: {url}")
        text = fetch_article_content(url)
        verify_content(text)

        title = fetch_title(url)
        if not title:
            title = "Essay"

        all_text.append(f"\n\n{title}. By Paul Graham.\n\n{text}")

    combined = "\n\n".join(all_text)
    cleaned = clean_text_for_tts(combined)
    print(f"Total characters: {len(cleaned)}")

    output_path = "/root/audiobook.mp3"
    success = create_audiobook(cleaned, output_path)
    if not success:
        print("Failed to create audiobook")
        return 1

    print(f"Audiobook created: {output_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
